let liveMap=null,mapGeneration=0,basePreference='Mapa';
function geometryOf(field){return field.boundary|| (field.rings?{type:'Polygon',coordinates:field.rings}:null)}
function map(fields,options={}){const generation=++mapGeneration;const features=fields.filter(f=>geometryOf(f));requestAnimationFrame(()=>mountMap(features,generation,options));return '<div class="maptools"><button id="fit-map">Enquadrar talhões</button><button id="locate-map">Minha localização</button><label><input id="show-boundaries" type="checkbox" checked> Limites</label></div><div id="interactive-map" aria-label="Mapa interativo dos talhões"></div><p id="map-status" role="status">'+(features.length?'Clique em um talhão para consultar os dados.':'Importe um KML para visualizar os limites. Talhões sem geometria não aparecem no mapa.')+'</p>'}
function mountMap(fields,generation,options={}){if(generation!==mapGeneration)return;const el=document.getElementById('interactive-map');if(!el)return;if(liveMap){liveMap.remove();liveMap=null}if(!window.L){el.innerHTML='<p>Não foi possível carregar o mapa.</p>';return}
 const m=liveMap=L.map(el,{scrollWheelZoom:false,maxZoom:20}).setView([-28.64,-53.61],7);
 const roads=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxNativeZoom:19,maxZoom:20,attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>'});
 const satellite=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxNativeZoom:19,maxZoom:20,attribution:'Tiles © Esri — Sources: Esri, Maxar, Earthstar Geographics, and the GIS User Community'});
 const labels=L.tileLayer('https://services.arcgisonline.com/ArcGIS/rest/services/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}',{maxNativeZoom:19,maxZoom:20,attribution:'Labels © Esri'});
 const hybrid=L.layerGroup([satellite,labels]);const bases={'Mapa':roads,'Satélite':satellite,'Híbrido':hybrid};bases[basePreference].addTo(m);L.control.layers(bases,null,{collapsed:false}).addTo(m);L.control.scale({imperial:false}).addTo(m);m.on('baselayerchange',e=>basePreference=e.name);
 const group=L.featureGroup().addTo(m);let selected=null;
 for(const f of fields){const layer=L.geoJSON(geometryOf(f),{style:{color:'#c5ef75',weight:3,fillColor:'#6da749',fillOpacity:.18}}).addTo(group);layer.bindTooltip(esc(f.name),{sticky:true});layer.bindPopup('<b>'+esc(f.name)+'</b><br>Propriedade: '+esc(parentName(f.farmId,'farms'))+'<br>Área: '+fmt(f.area)+' ha');layer.on('click',()=>{if(selected)selected.setStyle({color:'#c5ef75',weight:3});selected=layer;layer.setStyle({color:'#ffcd4b',weight:5});document.getElementById('map-status').textContent=f.name+' · '+fmt(f.area)+' ha';if(!options.onReady)m.fitBounds(layer.getBounds(),{padding:[35,35],maxZoom:17})})}
 const fit=()=>{if(group.getLayers().length)m.fitBounds(group.getBounds(),{padding:[25,25],maxZoom:17})};fit();document.getElementById('fit-map').onclick=fit;
 document.getElementById('show-boundaries').onchange=e=>e.target.checked?group.addTo(m):m.removeLayer(group);
 document.getElementById('locate-map').onclick=()=>{document.getElementById('map-status').textContent='Obtendo sua localização…';m.locate({setView:true,maxZoom:16,timeout:12000})};let locationMarker=null;m.on('locationfound',e=>{if(locationMarker)m.removeLayer(locationMarker);locationMarker=L.circleMarker(e.latlng,{radius:7,color:'#fff',fillColor:'#2978dc',fillOpacity:1}).addTo(m).bindPopup('Sua localização · precisão aproximada: '+Math.round(e.accuracy)+' m');document.getElementById('map-status').textContent='Localização encontrada.'});m.on('locationerror',()=>document.getElementById('map-status').textContent='Não foi possível obter sua localização. Confira a permissão do navegador.');
 let failures=0;for(const tiles of [roads,satellite,labels])tiles.on('tileerror',()=>{if(++failures>=3)document.getElementById('map-status').textContent='Algumas imagens não carregaram. Confira sua conexão ou troque a camada.'});
 if(options.onReady)options.onReady(m,group);
}
